import org.apache.http.impl.client.HttpClientBuilder
import org.apache.http.client.config.RequestConfig
import org.apache.http.impl.client.CloseableHttpClient

class Good1 {
    fun good(): CloseableHttpClient {
        val requestConfig = RequestConfig.custom()
            .setConnectionRequestTimeout(350)
            .setConnectTimeout(250)
            .setSocketTimeout(4000)
            .build() // good, all timeouts set
        return HttpClientBuilder.create()
            .setDefaultRequestConfig(requestConfig) // good
            .build()
    }
}

import org.apache.http.impl.client.HttpClientBuilder
import org.apache.http.client.config.RequestConfig
import org.apache.http.impl.client.CloseableHttpClient

class Bad1 {
    fun bad(): CloseableHttpClient {
        val requestConfig = RequestConfig.custom()
            .setSocketTimeout(4000)
            .build() // bad, not all timeouts set
        return HttpClientBuilder.create()
            .setDefaultRequestConfig(requestConfig)
            .build()
    }
}

import org.apache.http.impl.client.HttpClientBuilder
import org.apache.http.client.config.RequestConfig
import org.apache.http.impl.client.CloseableHttpClient
import java.util.concurrent.TimeUnit

class Bad2 {
    fun bad(): CloseableHttpClient {
        return HttpClientBuilder.create() // bad
            .setConnectionTimeToLive(180, TimeUnit.SECONDS)
            .build()
    }
}

import org.apache.http.client.HttpClient
import org.springframework.http.client.HttpComponentsClientHttpRequestFactory

class Good3 {
    fun good(): HttpClient {
        val factory = HttpComponentsClientHttpRequestFactory() // good
        factory.setConnectTimeout(250)
        factory.setConnectionRequestTimeout(350)
        factory.setReadTimeout(4000)
        return factory.httpClient
    }
}

import org.apache.http.client.HttpClient
import org.springframework.http.client.HttpComponentsClientHttpRequestFactory

class Bad4 {
    fun bad(): HttpClient {
        val factory = HttpComponentsClientHttpRequestFactory() // bad
        factory.setReadTimeout(4000)
        return factory.httpClient
    }
}
